SELECT first_name, last_name, name
FROM Customers NATURAL JOIN Products
WHERE category = 'Electronics' AND quantity >= 2 AND status = 'Paid';

SELECT country, COUNT(country)
FROM Customers
GROUP BY EXTRACT(YEAR FROM joined_at) = 2024, country <> 'Israel';

SELECT name
FROM Products
WHERE product_id IN (SELECT product_id FROM OrderItems);

SELECT C.first_name, C.last_name, O.order_id
FROM Customers C, Orders O, Sellers S
WHERE O.status = 'Cancelled' AND S.rating < 3.5;
